+void ChainScanner::UpdateTipIfChanged(LoopState& state) {
+    const uint256 new_tip = WITH_LOCK(m_wallet.cs_wallet, return m_wallet.GetLastBlockHash());
+    if (new_tip != state.tip_hash) {
+        state.tip_hash = new_tip;
